import 'dart:async';

void main() {
  print('A');
  Future(() => print('B'));
  scheduleMicrotask(() => print('C'));
  Future.microtask(() => print('D'));
  print('E');
}

Future<void> f() async {
  print('B');
  await Future(() {});
  print('D');
}

void main() {
  print('A');
  f();
  print('C');
}

Stream<int> count() async* {
  for (var i = 1; i <= 3; i++) {
    yield i;
  }
}

void main() async {
  final sum = await count().reduce((a, b) => a + b);
  print(sum);
}

Future<void> fail() async => throw 'x';

void main() {
  try {
    fail();
  } catch (e) {
    print('caught');
  }
}
